    #[test]
    fn captured_function_metadata_is_complete() {
        let data = fixture(); let expected = data["functions"].as_array().unwrap();
        assert_eq!(RAW_FUNCTION_SIGNATURES.len(), expected.len());
        for ((name, result, parameters), expected) in RAW_FUNCTION_SIGNATURES.iter().zip(expected) {
            assert_eq!(*name, expected["name"].as_str().unwrap());
            assert_eq!(*result, expected["result"].as_str().unwrap());
            assert_eq!(parameters.len(), expected["params"].as_array().unwrap().len());
            for (parameter, expected) in parameters.iter().zip(expected["params"].as_array().unwrap()) { assert_eq!(*parameter, expected.as_str().unwrap()); }
        }
    }
